From 44d3552aa56d0d44a00ed5c793ab894d2b6808ce Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:34:43 +0100
Subject: [PATCH] applets/mediacontroller: allow copying the title and artist

There was no way to copy the title and artist of the playing track, so
people had to type them out by hand. Add a "Copy Title and Artist" item
to the context menu, and copy the same text with Ctrl+C in the popup.

BUG: 409988
---
 .../ExpandedRepresentation.qml                |  5 +++++
 applets/mediacontroller/main.qml              | 20 +++++++++++++++++++
 2 files changed, 25 insertions(+)

diff --git a/applets/mediacontroller/ExpandedRepresentation.qml b/applets/mediacontroller/ExpandedRepresentation.qml
index 38d591fa14..cac864e908 100644
--- a/applets/mediacontroller/ExpandedRepresentation.qml
+++ b/applets/mediacontroller/ExpandedRepresentation.qml
@@ -82,6 +82,11 @@ PlasmaExtras.Representation {

     Keys.onPressed: event => {
         keyPressed = true
+        if (event.matches(StandardKey.Copy) && root.track) {
+            event.accepted = true;
+            root.copyTrackInfo();
+        }
+
         if ((event.key == Qt.Key_Tab || event.key == Qt.Key_Backtab) && event.modifiers & Qt.ControlModifier) {
             event.accepted = true;
             if (playerList.count > 2) {
diff --git a/applets/mediacontroller/main.qml b/applets/mediacontroller/main.qml
index e1a34a8dd5..88ab2ffd44 100644
--- a/applets/mediacontroller/main.qml
+++ b/applets/mediacontroller/main.qml
@@ -13,6 +13,7 @@ import org.kde.plasma.core as PlasmaCore
 import plasma.applet.org.kde.plasma.mediacontroller
 import org.kde.plasma.private.mpris as Mpris
 import org.kde.kirigami as Kirigami
+import org.kde.kquickcontrolsaddons as KQCAddons

 PlasmoidItem {
     id: root
@@ -150,6 +151,18 @@ PlasmoidItem {
             enabled: root.canStop
             onTriggered: root.stop()
         },
+        PlasmaCore.Action {
+            isSeparator: true
+            priority: PlasmaCore.Action.LowPriority
+            visible: root.track.length > 0
+        },
+        PlasmaCore.Action {
+            text: root.artist ? i18nc("@action:inmenu", "Copy Title and Artist") : i18nc("@action:inmenu", "Copy Title")
+            icon.name: "edit-copy-symbolic"
+            priority: PlasmaCore.Action.LowPriority
+            visible: root.track.length > 0
+            onTriggered: root.copyTrackInfo()
+        },
         PlasmaCore.Action {
             isSeparator: true
             priority: PlasmaCore.Action.LowPriority
@@ -203,12 +216,19 @@ PlasmoidItem {
             mpris2Model.currentPlayer.Quit();
         }
     }
+    function copyTrackInfo(): void {
+        clipboard.content = root.artist ? i18nc("@info:clipboard %1 is the track title and %2 is the artist", "%1 – %2", root.track, root.artist) : root.track;
+    }
     function raise(): void {
         if (mpris2Model.currentPlayer) {
             mpris2Model.currentPlayer.Raise();
         }
     }

+    KQCAddons.Clipboard {
+        id: clipboard
+    }
+
     Mpris.Mpris2Model {
         id: mpris2Model
     }
-- 
2.53.0
